// warehouse-map · кейс wm-12 (.qa/tests/warehouse-map/) — עובד מחסן через «כניסה כעובד» из admin-сессии, в конце «חזרה לחשבון הניהול».
import { test, expect } from '@playwright/test';
import { auth, impersonate, backToAdmin } from './_helpers';

test.use({ storageState: auth('admin') });

test('עובד מחסן רואה את מפת המחסן בלי «עריכת המפה» #6a5cb979 #6a859245 @desktop', async ({ page }) => {
  await impersonate(page, 'עובד מחסן בדיקה');
  await expect(page).toHaveURL(/\/warehouse\/map/);
  await expect(page.getByRole('heading', { level: 1, name: 'מפת המחסן' })).toBeVisible();
  await expect(page.getByRole('tablist', { name: 'קומות המחסן' })).toBeVisible();
  await expect(page.getByRole('button', { name: 'הוספת פריט', exact: true })).toBeVisible();
  await expect(page.getByRole('button', { name: 'החזרות' })).toBeVisible();
  await expect(page.getByRole('button', { name: 'עריכת המפה' })).toHaveCount(0);
  await backToAdmin(page);
});
